void ov80_02234BEC(BattleArcade *arcade, FrontierGraphics *graphics, u16 isOpponent) {
    u8 playerPartySize = BattleArcade_GetMonCount(arcade->challengeType, 1);
    u8 opponentPartySize = BattleArcade_GetOpponentMonCount(arcade->challengeType, 1);

    if (!isOpponent) {
        for (int i = 0; i < playerPartySize; i++) {
            arcade->playerItemSprites[i] = ov80_0222F3FC(graphics, ov80_0223BEB8[i].x + 8, ov80_0223BEB8[i].y + 4);

            Pokemon *mon = Party_GetMonByIndex(arcade->playersParty, i);

            if (GetMonData(mon, MON_DATA_HELD_ITEM_PT, ((void *)0)) == ITEM_NONE_PT) {
                Sprite_SetDrawFlag(arcade->playerItemSprites[i]->sprite, 0);
            }
        }
    } else {
        for (int i = 0; i < opponentPartySize; i++) {
            arcade->opponentItemSprites[i] = ov80_0222F3FC(graphics, ov80_0223BEC8[i].x + 8, ov80_0223BEC8[i].y + 4);

            Pokemon *mon = Party_GetMonByIndex(arcade->opponentsParty, i);

            if (GetMonData(mon, MON_DATA_HELD_ITEM_PT, ((void *)0)) == ITEM_NONE_PT) {
                Sprite_SetDrawFlag(arcade->opponentItemSprites[i]->sprite, 0);
            }
        }
    }
}
